PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, avatar TEXT DEFAULT '', role TEXT NOT NULL DEFAULT 'user', blocked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, last_login TEXT);
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_token_hash ON sessions(token_hash);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, color TEXT NOT NULL DEFAULT '#ef1523');
CREATE TABLE IF NOT EXISTS anime (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, synopsis TEXT NOT NULL DEFAULT '', cover TEXT NOT NULL DEFAULT '', banner TEXT NOT NULL DEFAULT '', logo TEXT NOT NULL DEFAULT '', year INTEGER, status TEXT NOT NULL DEFAULT 'Ongoing', score REAL NOT NULL DEFAULT 0, type TEXT NOT NULL DEFAULT 'TV', episodes INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0, release_day TEXT NOT NULL DEFAULT '', release_time TEXT NOT NULL DEFAULT '', tags_json TEXT NOT NULL DEFAULT '[]', categories_json TEXT NOT NULL DEFAULT '[]', anilist_id INTEGER, mal_id INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_anime_created ON anime(created_at);
CREATE INDEX IF NOT EXISTS idx_anime_views ON anime(views);
CREATE INDEX IF NOT EXISTS idx_anime_anilist ON anime(anilist_id);
CREATE TABLE IF NOT EXISTS episodes (id INTEGER PRIMARY KEY AUTOINCREMENT, anime_id INTEGER NOT NULL, season INTEGER NOT NULL DEFAULT 1, episode INTEGER NOT NULL, title TEXT NOT NULL, duration TEXT NOT NULL DEFAULT '24 min', language TEXT NOT NULL DEFAULT 'Legendado', stream_url TEXT NOT NULL DEFAULT '', download_url TEXT NOT NULL DEFAULT '', thumbnail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(anime_id,season,episode), FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_episodes_anime ON episodes(anime_id,season,episode);
CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, anime_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,anime_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS history (user_id INTEGER NOT NULL, anime_id INTEGER NOT NULL, episode_id INTEGER, progress REAL NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(user_id,anime_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_history_user ON history(user_id,updated_at);
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, anime_id INTEGER NOT NULL, parent_id INTEGER, body TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_comments_anime ON comments(anime_id,created_at);
CREATE TABLE IF NOT EXISTS sections (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, subtitle TEXT DEFAULT '', type TEXT NOT NULL DEFAULT 'manual', category_id INTEGER, anime_ids_json TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_sections_position ON sections(position);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER, action TEXT NOT NULL, target TEXT NOT NULL, meta_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_logs_created ON logs(created_at);
